#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define so vec2(.5,.3).y
mat2 rot(float a) {
    a=radians(a);
    float s=sin(a), c=cos(a);
    return mat2(c,s,-s,c);
}


vec3 fractal(vec2 p) {
    float a=smoothstep(-.1,.1,sin(iTime*.5));
    p*=rot(.5*iTime);  
    vec2 p2=p;

    p.y+=iTime*.3+so*.1+a;

    p=fract(p*.5);
    float m=100.;
    float it=0.;
    for (int i=0; i<10; i++) {
        p=abs(p)/clamp(abs(p.x*p.y),.25,2.)-1.;
        float l=abs(p.x);
        m=min(m,l);
        if (m==l) {
            it=float(i);
        }

    }
    float f=smoothstep(.015,.01,m*.5);
    f*=step(p2.y*.5+p2.x+it*.1-.3,.0);
    vec3 col=normalize(vec3(1.,.0,.5));
    col.rg*=rot(length(p2+it*.5)*200.);
    col=normalize(col+.5)+step(.5,fract(p2.y*100.));
    return col*(f*.9+.1)*(1.+so*10.);
}
void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
      vec2 uv = C / iResolution.xy - .5;
    uv.x*=iResolution.x/iResolution.y;


    int aa = 5; 
    float f=max(abs(uv.x),abs(uv.y));
    vec2 pixelSize = 1. / iResolution.xy / float(aa) * f;
    vec3 col = vec3(0.0); 
 vec2 offset=vec2(cos(iTime*0.1)*5.,5.);
    for (int i = -aa; i <= aa; i++)
    {
        for (int j = -aa; j <= aa; j++)
        {
             offset += vec2(float(i), float(j)) * pixelSize;

        }
    }

    vec3 p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1)); 

    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(1,.5,2.1),H(g*.1),.8)*5./e/8e3
    )
    {
        p=g*d;
         vec2 offset=vec2(p.x,p.y);
      p.z-=iTime;
        offset.yx*=rot(iTime*1.1);
        p.yx*=rot(iTime*1.1);

        a=30.;
        p=mod(p-a,a*2.)-a;
        s=3.;
        p+=fractal(uv + offset);
         p.yz*=rot(iTime*1.1);
        for(int i=0;i++<8;){

            p=.1-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.21)*.1;
            p=abs(p)*e-
                vec3(
                    10.*3.,
                    120,
                    8.*5.
                 );
         }
         g+=e=length(p.yzzz)/s;
    }
}
